<template>
  <section class="page suggestion-page">
    <div class="page-header"><h1>性能优化建议</h1><div><el-button @click="selectAll">全选</el-button><el-button type="primary" :disabled="!selectedIds.length" :icon="Download" @click="exportSelected">导出</el-button></div></div>
    <el-card shadow="never" class="filter-card"><el-form :inline="true" :model="query"><el-form-item label="ID搜索"><el-input v-model="query.keyword" clearable placeholder="优化建议ID" /></el-form-item><el-form-item label="任务名称"><el-input v-model="query.taskName" clearable placeholder="任务名称" /></el-form-item><el-form-item label="创建者"><el-input v-model="query.creatorName" clearable placeholder="创建者" /></el-form-item><el-form-item label="处理状态"><el-select v-model="query.processStatus" clearable placeholder="全部"><el-option label="未核对" value="PENDING" /><el-option label="确认" value="CONFIRMED" /><el-option label="误报" value="FALSE_POSITIVE" /><el-option label="已关闭" value="CLOSED" /></el-select></el-form-item><el-form-item><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="RefreshLeft" @click="reset">重置</el-button></el-form-item></el-form></el-card>
    <el-card shadow="never"><el-table ref="tableRef" v-loading="loading" :data="records" stripe row-key="id" empty-text="暂无数据" @selection-change="selectionChange"><el-table-column type="selection" width="55" /><el-table-column prop="reportCode" label="优化建议ID" width="150" /><el-table-column prop="taskNameSnapshot" label="任务名称" min-width="220" show-overflow-tooltip /><el-table-column prop="targetNameSnapshot" label="优化对象" min-width="180" show-overflow-tooltip /><el-table-column prop="optimizationProblem" label="优化问题" min-width="280" show-overflow-tooltip /><el-table-column prop="createdAt" label="创建时间" width="175"><template #default="{ row }">{{ formatTime(row.createdAt) }}</template></el-table-column><el-table-column prop="creatorName" label="创建者" width="110"><template #default="{ row }">{{ row.creatorName || '-' }}</template></el-table-column><el-table-column prop="processStatus" label="处理状态" width="110"><template #default="{ row }"><el-tag :type="statusType(row.processStatus)" round>{{ statusText(row.processStatus) }}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{ row }"><el-button type="primary" link :icon="View" @click="openDetail(row)">查看详情</el-button></template></el-table-column></el-table><div class="table-footer"><el-pagination v-model:current-page="query.pageNo" v-model:page-size="query.pageSize" :page-sizes="[10,20,50,100]" layout="total, sizes, prev, pager, next" :total="total" @change="load" /></div></el-card>
    <el-dialog v-model="detailVisible" title="性能优化建议详情" width="640px" class="detail-dialog" destroy-on-close><template v-if="detail"><div class="summary-grid"><div><label>优化对象</label><strong>{{ detail.targetNameSnapshot || '-' }}</strong></div><div><label>创建者</label><strong>{{ detail.creatorName || '-' }}</strong></div><div><label>优化建议ID</label><strong>{{ detail.reportCode || '-' }}</strong></div><div><label>创建时间</label><strong>{{ formatTime(detail.createdAt) }}</strong></div></div><article class="detail-section problem"><h3>待优化问题</h3><p>{{ detail.optimizationProblem || '-' }}</p></article><article class="detail-section data"><h3>待优化数据</h3><pre>{{ detail.sqlText || '-' }}</pre></article><article class="detail-section content"><h3>待优化内容</h3><p>{{ detail.optimizationContent || '-' }}</p></article></template><template #footer><div class="dialog-footer"><el-button v-if="canHandle" type="success" @click="handle('CONFIRMED')">确认正确</el-button><el-button v-if="canHandle" type="warning" @click="handle('FALSE_POSITIVE')">标记误报</el-button><el-button @click="detailVisible=false">关闭</el-button></div></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Download, RefreshLeft, Search, View } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox, type TableInstance } from 'element-plus'
import { exportOptimizationReports, getOptimizationReportDetail, getOptimizationReports, handleOptimizationReport, type OptimizationReportItem, type ProcessStatus } from '@/api/modules/ai'
import { useUserStore } from '@/stores/user'
const userStore=useUserStore(); const loading=ref(false); const total=ref(0); const records=ref<OptimizationReportItem[]>([]); const selectedIds=ref<string[]>([]); const tableRef=ref<TableInstance>(); const detailVisible=ref(false); const detail=ref<OptimizationReportItem|null>(null); const query=reactive({pageNo:1,pageSize:10,keyword:'',taskName:'',creatorName:'',processStatus:'' as ProcessStatus|''}); const canHandle=computed(()=>userStore.hasPermission('ai:optimization:handle'))
function formatTime(value?:string){return value?value.replace('T',' ').slice(0,19):'-'}; function statusText(value?:string){return ({PENDING:'未核对',CONFIRMED:'确认',FALSE_POSITIVE:'误报',CLOSED:'已关闭'} as Record<string,string>)[value||'']||'-'}; function statusType(value?:string){return value==='CONFIRMED'?'success':value==='FALSE_POSITIVE'?'warning':value==='CLOSED'?'info':'info'}; async function load(){loading.value=true;try{const page=await getOptimizationReports({pageNo:query.pageNo,pageSize:query.pageSize,keyword:query.keyword||undefined,taskName:query.taskName||undefined,creatorName:query.creatorName||undefined,processStatus:query.processStatus||undefined});records.value=page.records;total.value=page.total;selectedIds.value=[]}finally{loading.value=false}}; function search(){query.pageNo=1;load()}; function reset(){query.keyword='';query.taskName='';query.creatorName='';query.processStatus='';query.pageNo=1;load()}; function selectionChange(rows:OptimizationReportItem[]){selectedIds.value=rows.map(row=>row.id)}; function selectAll(){records.value.forEach(row=>tableRef.value?.toggleRowSelection(row,true))}; async function openDetail(row:OptimizationReportItem){detail.value=await getOptimizationReportDetail(row.id);detailVisible.value=true}; async function handle(status:ProcessStatus){if(!detail.value)return;await ElMessageBox.confirm(`确认将该优化建议标记为“${statusText(status)}”吗？`,'确认处理',{type:'warning'});await handleOptimizationReport(detail.value.id,status);ElMessage.success('处理成功');detailVisible.value=false;await load()}; async function exportSelected(){const response=await exportOptimizationReports(selectedIds.value);const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download='性能优化建议.csv';link.click();URL.revokeObjectURL(url);ElMessage.success('导出成功')};
load()
</script>
<style scoped>
.suggestion-page{min-width:0}.page-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-header h1{margin:0;font-size:22px;color:#1f2937;font-weight:600}.filter-card{margin-bottom:16px;border-radius:8px}.table-footer{display:flex;justify-content:flex-end;padding:16px 0 0}.detail-dialog:deep(.el-dialog){border-radius:12px;overflow:hidden}.detail-dialog:deep(.el-dialog__body){padding:0 20px 18px}.summary-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 34px;padding:18px 14px;background:#fbfcfe;border-radius:10px}.summary-grid label{display:block;margin-bottom:7px;color:#94a3b8;font-size:12px}.summary-grid strong{color:#25324a;font-size:14px}.detail-section{margin-top:16px;padding:18px 20px;border:1px solid #dce6f5;border-radius:12px;box-shadow:0 4px 14px rgba(36,89,166,.06)}.detail-section h3{margin:0 0 14px;padding-left:10px;border-left:4px solid #2f6fe4;color:#1e293b;font-size:16px}.detail-section.data h3{border-left-color:#ff7a00}.detail-section.content h3{border-left-color:#16a34a}.detail-section p{margin:0;color:#334155;font-size:14px;line-height:1.8}.detail-section pre{margin:0;padding:14px;border-radius:10px;background:#111827;color:#e5e7eb;font:13px/1.6 Consolas,monospace;white-space:pre-wrap}.dialog-footer{display:flex;justify-content:flex-end;gap:10px}@media(max-width:720px){.summary-grid{grid-template-columns:1fr}}
</style>
